import { t, getLocale } from '../i18n/index.js';
import { localeTag } from '../i18n/formatters.js';
import { esc } from '../core/utils.js';
import { openDetail, toast } from './components.js';

const n=v=>Number.isFinite(Number(v))?Number(v):0;
const moneyMinor=v=>new Intl.NumberFormat(localeTag(getLocale()),{style:'currency',currency:'EUR',maximumFractionDigits:2}).format(n(v)/100);
const number=v=>new Intl.NumberFormat(localeTag(getLocale()),{maximumFractionDigits:2}).format(n(v));
const delta=(cur,prev)=>{const a=n(cur),b=n(prev);if(!b)return a?null:0;return Math.round(((a-b)/Math.abs(b))*1000)/10;};
const deltaHtml=(cur,prev)=>{const d=delta(cur,prev);if(d==null)return `<span class="kx-r77-delta neutral">${esc(t('common.analytics.newPeriod'))}</span>`;const cls=d>0?'up':d<0?'down':'neutral';return `<span class="kx-r77-delta ${cls}">${d>0?'+':''}${number(d)}%</span>`;};
const pct=v=>`${number(v)} %`;
const conversion=data=>n(data?.current?.views)>0?100*n(data?.current?.purchases||data?.current?.orders)/n(data.current.views):0;
const pad=v=>String(v).padStart(2,'0');
const inputDate=d=>`${d.getFullYear()}-${pad(d.getMonth()+1)}-${pad(d.getDate())}`;
const parseInputDate=value=>{const m=String(value||'').match(/^(\d{4})-(\d{2})-(\d{2})$/);return m?new Date(Number(m[1]),Number(m[2])-1,Number(m[3]),0,0,0,0):null;};

export function resolveAnalyticsPeriod(value=30,customFrom='',customTo=''){
  if(value&&typeof value==='object'&&value.from&&value.to)return {...value,key:String(value.key||'custom'),days:Math.max(1,Number(value.days)||1)};
  const key=String(value||'30'),now=new Date();let from,to=now,fromDate='',toDate='';
  if(key==='month')from=new Date(now.getFullYear(),now.getMonth(),1,0,0,0,0);
  else if(key==='prev_month'){from=new Date(now.getFullYear(),now.getMonth()-1,1,0,0,0,0);to=new Date(now.getFullYear(),now.getMonth(),1,0,0,0,0);}
  else if(key==='custom'){
    const start=parseInputDate(customFrom),end=parseInputDate(customTo);
    if(!start||!end||end<start)return null;
    from=start;to=new Date(end.getFullYear(),end.getMonth(),end.getDate()+1,0,0,0,0);fromDate=inputDate(start);toDate=inputDate(end);
  }else{const days=Math.min(365,Math.max(1,Number(key)||30));from=new Date(now.getTime()-days*86400000);}
  const days=Math.max(1,Math.ceil((to-from)/86400000));
  if(days>366)return null;
  return {key,days,from:from.toISOString(),to:to.toISOString(),fromDate:fromDate||inputDate(from),toDate:toDate||inputDate(new Date(to.getTime()-1))};
}
function periodLabel(period){const p=resolveAnalyticsPeriod(period)||resolveAnalyticsPeriod(30);const keys={'7':'common.analytics.period7','30':'common.analytics.period30','month':'common.analytics.periodCurrentMonth','prev_month':'common.analytics.periodPreviousMonth','90':'common.analytics.periodQuarter','365':'common.analytics.periodYear'};return p.key==='custom'?`${p.fromDate} — ${p.toDate}`:t(keys[p.key]||'common.analytics.period30');}
function periodPicker(scope,id,period){
  const p=resolveAnalyticsPeriod(period)||resolveAnalyticsPeriod(30),opts=[['7','common.analytics.period7'],['30','common.analytics.period30'],['month','common.analytics.periodCurrentMonth'],['prev_month','common.analytics.periodPreviousMonth'],['90','common.analytics.periodQuarter'],['365','common.analytics.periodYear'],['custom','common.analytics.periodCustom']];
  return `<div class="kx-r77-period" data-r77-period-root="${esc(id)}"><label><span>${esc(t('common.analytics.period'))}</span><select id="${esc(id)}">${opts.map(([v,k])=>`<option value="${v}" ${p.key===v?'selected':''}>${esc(t(k))}</option>`).join('')}</select></label><div class="kx-r77-custom-period" ${p.key==='custom'?'':'hidden'}><label><span>${esc(t('common.analytics.from'))}</span><input type="date" data-r77-from value="${esc(p.fromDate)}"></label><label><span>${esc(t('common.analytics.to'))}</span><input type="date" data-r77-to value="${esc(p.toDate)}"></label><button type="button" class="btn btn-ghost btn-sm" data-r77-apply-period>${esc(t('common.analytics.applyPeriod'))}</button></div><small>${esc(t(scope==='event'?'events.analytics.periodHint':'showcase.analytics.periodHint'))}</small></div>`;
}
function bindPeriodPicker(modal,id,period,onChange,{instant=true}={}){
  const select=modal.wrap.querySelector(`#${id}`),root=modal.wrap.querySelector(`[data-r77-period-root="${id}"]`),custom=root?.querySelector('.kx-r77-custom-period');
  const run=async()=>{const spec=resolveAnalyticsPeriod(select?.value,root?.querySelector('[data-r77-from]')?.value,root?.querySelector('[data-r77-to]')?.value);if(!spec){toast(t('common.analytics.invalidPeriod'),'error');return null;}await onChange?.(spec);return spec;};
  select?.addEventListener('change',async()=>{const isCustom=select.value==='custom';if(custom)custom.hidden=!isCustom;if(!isCustom&&instant)await run();});
  root?.querySelector('[data-r77-apply-period]')?.addEventListener('click',run);
  return ()=>resolveAnalyticsPeriod(select?.value,root?.querySelector('[data-r77-from]')?.value,root?.querySelector('[data-r77-to]')?.value)||resolveAnalyticsPeriod(period);
}
function chart(series=[],field='gross_minor',money=false){
  const rows=Array.isArray(series)?series.slice(-31):[];const max=Math.max(1,...rows.map(r=>n(r[field])));
  if(!rows.length)return `<div class="kx-r77-empty-chart">${esc(t('common.analytics.noData'))}</div>`;
  return `<div class="kx-r77-histogram" role="img" aria-label="${esc(t('common.analytics.histogram'))}">${rows.map((r,i)=>{const value=n(r[field]),h=Math.max(value?4:1,Math.round(value/max*100));return `<div class="kx-r77-bar" title="${esc(r.date||'')} · ${esc(money?moneyMinor(value):number(value))}"><i style="height:${h}%"></i>${(rows.length<=12||i%Math.ceil(rows.length/8)===0)?`<span>${esc(String(r.date||'').slice(5))}</span>`:''}</div>`;}).join('')}</div>`;
}
function kpi(label,value,cur=null,prev=null,sub=''){return `<article class="kx-r77-kpi"><small>${esc(label)}</small><strong>${esc(String(value))}</strong>${cur!==null?deltaHtml(cur,prev):''}${sub?`<span>${esc(sub)}</span>`:''}</article>`;}
function productTable(products=[]){
  const rows=(Array.isArray(products)?products:[]).slice(0,18);if(!rows.length)return `<div class="kx-r77-empty-chart">${esc(t('common.analytics.noData'))}</div>`;
  return `<div class="kx-r77-table-wrap"><table class="kx-r77-table"><thead><tr><th>${esc(t('showcase.analytics.product'))}</th><th>${esc(t('showcase.analytics.units'))}</th><th>${esc(t('showcase.analytics.revenue'))}</th><th>${esc(t('showcase.analytics.views'))}</th><th>${esc(t('showcase.analytics.conversion'))}</th><th>${esc(t('showcase.analytics.stock'))}</th></tr></thead><tbody>${rows.map(p=>`<tr><td><div class="kx-r77-product-cell"><span class="kx-r77-product-thumb">${p.image_url?`<img src="${esc(p.image_url)}" alt="">`:'<b>K</b>'}</span><strong>${esc(p.name||t('showcase.analytics.product'))}</strong></div></td><td>${number(p.units)}</td><td>${moneyMinor(p.revenue_minor)}</td><td>${number(p.views)}</td><td>${p.conversion_percent==null?'—':pct(p.conversion_percent)}</td><td>${p.stock==null?'—':number(p.stock)}</td></tr>`).join('')}</tbody></table></div>`;
}
function categoryBars(categories=[]){const rows=(Array.isArray(categories)?categories:[]).slice(0,8),max=Math.max(1,...rows.map(r=>n(r.revenue_minor)));if(!rows.length)return `<div class="kx-r77-empty-chart">${esc(t('common.analytics.noData'))}</div>`;return `<div class="kx-r77-horizontal-bars">${rows.map(r=>`<article><header><strong>${esc(r.category||t('showcase.analytics.uncategorized'))}</strong><span>${moneyMinor(r.revenue_minor)}</span></header><div><i style="width:${Math.max(2,Math.round(n(r.revenue_minor)/max*100))}%"></i></div><small>${number(r.units)} ${esc(t('showcase.analytics.unitsShort'))}</small></article>`).join('')}</div>`;}
function eventResults(results={}){return `<div class="kx-r77-result-grid">${kpi(t('events.analytics.fights'),number(results.total))}${kpi(t('events.analytics.completed'),number(results.completed))}${kpi('KO/TKO',number(results.ko_tko))}${kpi(t('events.analytics.submissions'),number(results.submissions))}${kpi(t('events.analytics.decisions'),number(results.decisions))}${kpi(t('events.analytics.cancelled'),number(results.cancelled))}</div>`;}

export function analyticsSummaryHtml(scope,data={}){const cur=data.current||{},prev=data.previous||{};if(scope==='event')return `<div class="kx-r77-summary-strip event">${kpi(t('events.analytics.revenue'),moneyMinor(cur.gross_minor),cur.gross_minor,prev.gross_minor)}${kpi(t('events.analytics.tickets'),number(cur.tickets),cur.tickets,prev.tickets)}${kpi(t('events.analytics.checkins'),number(cur.checkins))}${kpi(t('events.analytics.capacity'),number(cur.capacity))}</div>`;return `<div class="kx-r77-summary-strip showcase">${kpi(t('showcase.analytics.revenue'),moneyMinor(cur.gross_minor),cur.gross_minor,prev.gross_minor)}${kpi(t('showcase.analytics.orders'),number(cur.orders),cur.orders,prev.orders)}${kpi(t('showcase.analytics.units'),number(cur.units))}${kpi(t('showcase.analytics.views'),number(cur.views),cur.views,prev.views)}</div>`;}

export function openPremiumAnalytics({scope,entity,data,period=30,onReload,onReports}){
  const cur=data?.current||{},prev=data?.previous||{};const event=scope==='event';const title=event?t('events.analytics.title'):t('showcase.analytics.title');const spec=resolveAnalyticsPeriod(period)||resolveAnalyticsPeriod(30);
  const kpis=event?`${kpi(t('events.analytics.revenue'),moneyMinor(cur.gross_minor),cur.gross_minor,prev.gross_minor)}${kpi(t('events.analytics.orders'),number(cur.orders),cur.orders,prev.orders)}${kpi(t('events.analytics.tickets'),number(cur.tickets),cur.tickets,prev.tickets)}${kpi(t('events.analytics.averageTicket'),moneyMinor(cur.ticket_average_minor))}${kpi(t('events.analytics.checkins'),number(cur.checkins))}${kpi(t('events.analytics.buyers'),number(cur.buyers),cur.buyers,prev.buyers)}${kpi(t('events.analytics.capacity'),number(cur.capacity))}${kpi(t('events.analytics.participants'),number(cur.participants))}`:`${kpi(t('showcase.analytics.revenue'),moneyMinor(cur.gross_minor),cur.gross_minor,prev.gross_minor)}${kpi(t('showcase.analytics.orders'),number(cur.orders),cur.orders,prev.orders)}${kpi(t('showcase.analytics.averageTicket'),moneyMinor(cur.ticket_average_minor))}${kpi(t('showcase.analytics.units'),number(cur.units))}${kpi(t('showcase.analytics.views'),number(cur.views),cur.views,prev.views)}${kpi(t('showcase.analytics.interest'),number(cur.interest))}${kpi(t('showcase.analytics.buyers'),number(cur.buyers),cur.buyers,prev.buyers)}${kpi(t('showcase.analytics.conversion'),pct(conversion(data)))}`;
  const body=`<div class="kx-r77-analytics ${event?'is-events':'is-showcase'}">${periodPicker(scope,'kx-r77-period-select',spec)}<section class="kx-r77-kpi-grid">${kpis}</section><section class="kx-r77-panel"><header><div><span class="page-kicker">${esc(t('common.analytics.histogram'))}</span><h4>${esc(t(event?'events.analytics.salesEvolution':'showcase.analytics.salesEvolution'))}</h4></div><strong>${moneyMinor(cur.gross_minor)}</strong></header>${chart(data?.series,'gross_minor',true)}</section>${event?`<section class="kx-r77-panel"><header><div><span class="page-kicker">${esc(t('events.analytics.results'))}</span><h4>${esc(t('events.analytics.sportResults'))}</h4></div></header>${eventResults(data?.results||{})}</section>`:`<div class="kx-r77-two-column"><section class="kx-r77-panel"><header><div><span class="page-kicker">${esc(t('showcase.analytics.categories'))}</span><h4>${esc(t('showcase.analytics.categoryRevenue'))}</h4></div></header>${categoryBars(data?.categories||[])}</section><section class="kx-r77-panel"><header><div><span class="page-kicker">${esc(t('showcase.analytics.products'))}</span><h4>${esc(t('showcase.analytics.topProducts'))}</h4></div></header>${productTable(data?.products||[])}</section></div>`}</div>`;
  const modal=openDetail({title,subtitle:`${entity?.name||entity?.nombre||''} · ${periodLabel(spec)}`,width:'1180px',className:`kx-r77-analytics-modal ${event?'is-events':'is-showcase'}`,body,actions:`<button type="button" class="btn btn-ghost" id="kx-r77-open-reports">${esc(t('common.analytics.reports'))}</button>`});
  bindPeriodPicker(modal,'kx-r77-period-select',spec,async next=>{modal.close();await onReload?.(next)});
  modal.wrap.querySelector('#kx-r77-open-reports')?.addEventListener('click',()=>{modal.close();onReports?.(spec);});return modal;
}

const REPORTS={showcase:['general','sales','finance','products','stock','orders','performance'],event:['general','sales','finance','tickets','attendance','participants','fights','results','executive']};
export function openReportsCenter({scope,entity,period=30,generate}){
  const event=scope==='event',types=REPORTS[scope]||[],spec=resolveAnalyticsPeriod(period)||resolveAnalyticsPeriod(30);const label=k=>t(`${event?'events':'showcase'}.reports.types.${k}`);
  const modal=openDetail({title:t(`${event?'events':'showcase'}.reports.title`),subtitle:`${entity?.name||entity?.nombre||''} · ${t('common.analytics.privateReports')}`,width:'1020px',className:`kx-r77-reports-modal ${event?'is-events':'is-showcase'}`,body:`<div class="kx-r77-reports"><div class="kx-r77-report-head">${periodPicker(scope,'kx-r77-report-period',spec)}<p>${esc(t(`${event?'events':'showcase'}.reports.description`))}</p></div><div class="kx-r77-report-grid">${types.map(type=>`<article><span class="kx-r77-report-icon">PDF</span><div><strong>${esc(label(type))}</strong><small>${esc(t(`${event?'events':'showcase'}.reports.help.${type}`))}</small></div><button type="button" class="btn ${type==='general'||type==='results'?'btn-primary':'btn-ghost'} btn-sm" data-r77-report="${esc(type)}">${esc(t('common.analytics.generatePdf'))}</button></article>`).join('')}</div><div class="kx-r77-report-status" id="kx-r77-report-status" aria-live="polite"></div></div>`});
  const readPeriod=bindPeriodPicker(modal,'kx-r77-report-period',spec,()=>{}, {instant:false});
  modal.wrap.querySelectorAll('[data-r77-report]').forEach(button=>button.addEventListener('click',async()=>{const type=button.dataset.r77Report,current=readPeriod(),status=modal.wrap.querySelector('#kx-r77-report-status');if(!current){toast(t('common.analytics.invalidPeriod'),'error');return;}button.disabled=true;const original=button.textContent;button.textContent=t('common.analytics.generating');let popup=null;try{popup=window.open('about:blank','_blank');if(status)status.textContent=t('common.analytics.generating');const out=await generate(type,current);if(!out?.url)throw new Error(t('common.analytics.reportError'));if(popup&&!popup.closed)popup.location.href=out.url;else{const a=document.createElement('a');a.href=out.url;a.target='_blank';a.rel='noopener';a.download=out.filename||'';document.body.append(a);a.click();a.remove();}if(status)status.innerHTML=`<strong>${esc(t('common.analytics.reportReady'))}</strong><span>${esc(out.filename||label(type))}</span>`;toast(t('common.analytics.reportReady'));}catch(error){try{popup?.close();}catch{}if(status)status.textContent=error?.message||t('common.analytics.reportError');toast(error?.message||t('common.analytics.reportError'),'error');}finally{button.disabled=false;button.textContent=original;}}));return modal;
}
